    node.error("No hay tabla seleccionada");
    return null;
}

let cols = "*";

if(columnas && columnas.length > 0){
    cols = columnas.join(",");
}

let sql = `SELECT ${cols} FROM ${tabla}`;

if(inicio && fin){
    let startEpoch = Math.floor(new Date(inicio).getTime()/1000);
    let endEpoch = Math.floor(new Date(fin).getTime()/1000);
    sql += ` WHERE dateTime BETWEEN ${startEpoch} AND ${endEpoch}`;
}

sql += " LIMIT 100";

msg.topic = sql;

